input.command:
cd $SANDBOX_ROOT/gen-sara-harnessweaver-20261029T135951 && python3 - <<'E'
import re,glob,yaml,json,hashlib
B="generated/build/deepagents"; w=yaml.safe_load(open(f"{B}/wiring.yaml"))
avail={p["path"].split("/")[-1] for p in w["inputs"]}; bad=[]
for s in w["stages"]:
    produced=set(s["artifacts"])
    for f in glob.glob(f"{B}/{s['dir']}/**/*.md",recursive=True):
        for r in set(re.findall(r"/artifacts/([\w]+\.json)",open(f).read())):
            if r not in avail|produced: bad.append((f,r))
    avail|=produced
    for a,sc in s["schemas"].items(): json.load(open(f"{B}/{sc}"))
print("unresolved reads:",bad)
m=json.load(open("manifest.json"))["inputs"]
print("source changes:",[k for k,v in m.items() if k.startswith("sources/") and hashlib.sha256(open(k,"rb").read()).hexdigest()!=v])
E
grep -rln "adr\.md\|\.mmd\|decision-packaging\|architecture_diagram\.json" generated/build/deepagents | grep -v materialization-report; find generated -type f | sort

